def.body:
@client.on_message do |envelope|
  if ignored_reply?(envelope)
    next
  end
  if @waiting >= @max_waiting
    reject_busy(envelope)
    next
  end

  @waiting = @waiting + 1
  spawn do
    @slots.send(nil)
    @waiting = @waiting - 1
    begin
      handle(envelope)
    ensure
      @slots.receive
    end
  end
end

