id

@mutex.synchronize do
  @cache.clear
  @order.clear
  @db.try do |db| db.memo_queries.clear_query_cache(@service_id) end
end

@mutex.synchronize do
  if entry = @cache[query]?
    touch(query)
    @hits = @hits + 1
    {entry.embedding, entry.token_count}
  elsif db = @db
    if row = db.memo_queries.get_query_cache(query, @service_id)
      embedding_blob, token_count = row
      embedding = Storage.deserialize_embedding(embedding_blob)
      put_memory(query, embedding, token_count)
      @hits = @hits + 1
      {embedding, token_count}
    else
      @misses = @misses + 1
      nil
    end
  else
    @misses = @misses + 1
    nil
  end
end

@write_lock.synchronize do
  if @usearch_index.closed? || ((@unsaved_changes == 0) && (!@index_out_of_step))
    next
  end

  if @index_out_of_step
    IndexJournal.catch_up(@db, @usearch_index, @service_id, @index_path)
    @index_out_of_step = false
  end
  IndexJournal.checkpoint(@db, @usearch_index, @service_id, @index_path)
  @unsaved_changes = 0
  @saved_at = Time.instant
end

svc = ServiceProvider.get_by_name(@db, name)
if svc
else
  raise(ArgumentError.new("Service '#{name}' not found"))
end


provider_instance = Providers::Registry.create(svc.format, api_key, svc.model, svc.base_url, svc.dimensions)
if provider_instance
else
  raise(ArgumentError.new("Unknown format: #{svc.format}"))
end


save_index
@usearch_index.close
@index_lock.close

@provider = provider_instance
@service_name = name
@service_id = svc.id
@service_format = svc.format
@service_model = svc.model
@dimensions = svc.dimensions


@index_path = if db_p = @db_path
  USearchIndex.index_path(db_p, svc.format, svc.model, svc.dimensions)
else
  USearchIndex.index_path_in_dir(USearchIndex::DEFAULT_INDEX_DIR, svc.format, svc.model, svc.dimensions)
end
@usearch_index, @index_recovery, @index_lock = IndexJournal.open(@db, @index_path, svc.dimensions, @service_id)
@index_out_of_step = false
@unsaved_changes = 0
@saved_at = Time.instant

if File.exists?(path)
  begin
    return {USearch::Index.load(path, dimensions: dimensions, metric: :cos, quantization: :f16), true}
  rescue
  end
end
Dir.mkdir_p(File.dirname(path))
{USearch::Index.new(dimensions: dimensions, metric: :cos, quantization: :f16), false}

if index.contains?(key)
  index.remove(key)
end

